const fetch = global.get('fetch');
const res = await fetch(`${env.get('WORKER_URL')}/api/runs/bridge-start`, {
  method: 'POST',
  headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${env.get('WORKER_TOKEN')}` },
  body: JSON.stringify({ workflow_id: 'wf_client_followup' })
});
const data = await res.json();
if (!res.ok) { throw new Error(`bridge-start ${res.status}: ${JSON.stringify(data)}`); }
msg.run_id = data.run_id;
msg.payload = { run_id: data.run_id, ack: 'accepted' };
// Fork: output 1 = the ORIGINAL msg keeps the live http res (202 ack goes out now);
// output 2 = a clone WITHOUT res carries the async work chain (cloneMessage would
// deep-copy msg.res into a dead object — the response must never ride the clone).
const work = RED.util.cloneMessage(msg);
delete work.res;
// Return-mode function: the return value fans out per output. Output 1 = original msg
// with the live http res (202 ack), output 2 = res-less clone for the async work chain.
return [msg, work];

node.status({ fill: 'red', shape: 'ring', text: 'run failed' });
const fetch = global.get('fetch');
try {
  if (msg.run_id) {
    await fetch(`${env.get('WORKER_URL')}/api/runs/${msg.run_id}/complete`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${env.get('WORKER_TOKEN')}` },
      body: JSON.stringify({ run_id: msg.run_id, status: 'failed',
        error: String((msg.error && (msg.error.message || msg.error)) || 'node error') })
    });
  }
} catch (e) { node.error(`fail-complete: ${e.message}`); }
return null;
